#include "FileStuff.h"#include "crc.h"void FileRead ( void *theDest, long theLength, short theFileRef ){	FSRead ( theFileRef, &theLength, theDest);}void FileWrite ( void *theSrc, long theLength, short theFileRef ){	FSWrite ( theFileRef, &theLength, theSrc);}void FileSeek ( short theFileRef, long thePos ){	SetFPos ( theFileRef, fsFromStart, thePos);}void FilePutChar ( int theData, short theFileRef ){	long theLength = 1L;	char theChar = (char) theData;		FSWrite ( theFileRef, &theLength, &theChar );}OSErr FileCopy ( FSSpec theSrcFSSpec, FSSpec &theDestFSSpec, long *theLength ){	char			theBuffer[32000];	short			theSrcFileRef, theDestFileRef;	long			readCount = 32000L;	OSErr		theError;//---------------------------------------------------------	theError = FSpOpenDF ( &theSrcFSSpec, fsRdPerm, &theSrcFileRef );	if ( theError != noErr )		return theError;	theError = FSpCreate ( &theDestFSSpec, 'Myth', '????', smSystemScript );	theError = FSpOpenDF ( &theDestFSSpec, fsWrPerm, &theDestFileRef );	if ( theError != noErr ){		FSClose ( theSrcFileRef );		return theError;	}	*theLength = 0L;	SetEOF ( theDestFileRef, 0L );	do {			FSRead ( theSrcFileRef, &readCount, theBuffer );			FSWrite ( theDestFileRef, &readCount, theBuffer );			*theLength += readCount;		} while( readCount == 32000L );		GetEOF ( theSrcFileRef, theLength );	FSClose ( theSrcFileRef );	FSClose ( theDestFileRef );		return 0;}OSErr FileAppend ( FSSpec theSrcFSSpec, short theDestFileRef, long theStartOffset, unsigned long *theCRC ){	OSErr				theError;	char				theBuffer[32000];	short				theSrcFileRef;	long				readCount = 32000L;//---------------------------------------------------------	theError = FSpOpenDF ( &theSrcFSSpec, fsRdPerm, &theSrcFileRef );	if ( theError != noErr )		return theError;	SetFPos ( theSrcFileRef, fsFromStart, theStartOffset );		do {			FSRead ( theSrcFileRef, &readCount, theBuffer );			FSWrite ( theDestFileRef, &readCount, theBuffer );			crc_checksum_buffer ( theCRC, theBuffer, readCount );		} while( readCount == 32000L );		FSClose ( theSrcFileRef );	return theError;}